-- @mode multi_vendor
CREATE TABLE IF NOT EXISTS seller_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,shop_name VARCHAR(190) NOT NULL,shop_slug VARCHAR(190) NOT NULL UNIQUE,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,status VARCHAR(20) NOT NULL DEFAULT 'pending',CONSTRAINT fk_seller_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS seller_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,entry_type VARCHAR(30) NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_seller_ledger_order_entry(seller_id,order_id,entry_type),CONSTRAINT fk_ledger_seller FOREIGN KEY(seller_id) REFERENCES seller_profiles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS seller_withdrawals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',note VARCHAR(500) NULL,admin_note VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_withdrawal_seller(seller_id,status),CONSTRAINT fk_withdrawal_seller FOREIGN KEY(seller_id) REFERENCES seller_profiles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- @add-column products seller_id BIGINT UNSIGNED NULL
-- @add-column order_items seller_id BIGINT UNSIGNED NULL
-- @add-column order_items seller_commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00
-- @unique-index seller_ledger uq_seller_ledger_order_entry seller_id,order_id,entry_type